import{c as a,Q as e,j as o,m as r}from"./chunks/framework.BPKcPtvA.js";const d=JSON.parse('{"title":"启燃测试七天，巴哈快吵翻了——测试玩家到底在骂什么","description":"RO3启燃测试刚结束，巴哈姆特30+回复的吐槽帖一堆。从商城宠物到精炼系统，老玩家到底在气什么？整理了论坛真实声音。","frontmatter":{"title":"启燃测试七天，巴哈快吵翻了——测试玩家到底在骂什么","date":"2026-07-02T00:00:00.000Z","description":"RO3启燃测试刚结束，巴哈姆特30+回复的吐槽帖一堆。从商城宠物到精炼系统，老玩家到底在气什么？整理了论坛真实声音。"},"headers":[],"relativePath":"news/ignition-test-review.md","filePath":"news/ignition-test-review.md","lastUpdated":1783172399000}'),n={name:"news/ignition-test-review.md"};function p(s,t,i,l,u,h){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="启燃测试七天-巴哈快吵翻了——测试玩家到底在骂什么" tabindex="-1">启燃测试七天，巴哈快吵翻了——测试玩家到底在骂什么 <a class="header-anchor" href="#启燃测试七天-巴哈快吵翻了——测试玩家到底在骂什么" aria-label="Permalink to &quot;启燃测试七天，巴哈快吵翻了——测试玩家到底在骂什么&quot;">​</a></h1><blockquote><p>2026-07-02</p></blockquote><p>启燃测试今天结束了。七天时间，巴哈姆特RO3版的帖子从之前的零星几篇变成了几百篇，回复量也炸了。但大部分帖子的画风——不太好看。</p><p>我把巴哈上回复最多的几个帖子整理了一下，不是带节奏，就是把玩家真实在骂的东西摆出来，你自己判断。</p><h2 id="最火的帖子" tabindex="-1">最火的帖子 <a class="header-anchor" href="#最火的帖子" aria-label="Permalink to &quot;最火的帖子&quot;">​</a></h2><p><strong>&quot;显然是个垃圾游戏&quot;</strong>（6110浏览，64回复）。这个帖子标题够狠，但别急着跳过。点进去看内容，骂的人其实不是真的说游戏是垃圾，更多是恨铁不成钢。有人花了一整段讲自己从小学玩RO1到现在快30岁了，看到RO3又是商城一堆东西，心凉了半截。</p><p><strong>&quot;理性讨论，这游戏有没有前途&quot;</strong>（5212浏览，103回复）。这是目前版上回复最多的帖子。有人很理性地分析了RO3的系统——宠物是SSR/UR抽卡制、精炼要氪材料、活动绑定时间太死、掉落有疲劳值。结论是&quot;短期能赚一波，长期大概率凉&quot;。但也有反驳的，说&quot;先改了再说，测试本来就是用来改的&quot;。</p><p><strong>&quot;启燃测试结束，RO3能成为下一款20年的RO吗&quot;</strong>（611玩家观点）。这篇回复最多，有30个。大部分人的看法是：游戏底子不差，但商业模式不改就没戏。有个回复说得很直接——&quot;RO的核心是自由和探索，你现在给我套一堆限制，那还是RO吗？&quot;</p><h2 id="到底在骂什么" tabindex="-1">到底在骂什么 <a class="header-anchor" href="#到底在骂什么" aria-label="Permalink to &quot;到底在骂什么&quot;">​</a></h2><p>从回复里归纳一下，玩家不满的点基本就这四个：</p><p><strong>1. 宠物系统太氪</strong></p><p>RO3的宠物是抽卡制，有SSR、UR品质。帮打怪、给属性加成，品质越高越强。这基本上就是手游那套——你运气好抽到UR就比别人强，氪金概率拉满。老玩家的反应很一致：RO什么时候变成宠物对战了？</p><p><strong>2. 精炼系统</strong></p><p>有测试玩家发帖说&quot;精炼太坑&quot;。具体怎么坑的，说法不一。有人说失败率高，有人说需要的材料太贵，有人说跟RO1的精炼完全是两回事。精炼是RO老玩家最在意的系统之一，如果这块搞砸了，口碑基本就没了。</p><p><strong>3. 活动绑定时间太死</strong></p><p>有帖子提到&quot;绑时间活动与奖励&quot;——意思是有些活动必须在特定时间做，错过就没了。对上班族来说很不友好。RO1当年能火20年，一个重要原因就是你什么时候上线都能玩，不卡时间。</p><p><strong>4. 掉落有疲劳值</strong></p><p>这个争议最大。有玩家说打怪有疲劳值限制，打够了就不掉东西了。这等于逼你每天只能玩固定时间，不能像以前那样想肝就肝。制作人在直播里好像解释过，但玩家不太买账。</p><h2 id="也有正面声音" tabindex="-1">也有正面声音 <a class="header-anchor" href="#也有正面声音" aria-label="Permalink to &quot;也有正面声音&quot;">​</a></h2><p>别光看骂的。也有不少帖子是正面评价：</p><p><strong>&quot;RO3测试体验 Part 1&quot;</strong>（43回复，1608浏览）——这个帖子的作者给了比较中肯的评价。他说画面确实比以前的RO手游好很多，手感接近PC端游的感觉，副本有机制不是站桩。但他也说了&quot;商业模式需要改进，可以观望&quot;。</p><p><strong>&quot;这真的是RO续作？超出意料的制作人直播&quot;</strong>——作者看了制作人6月28日的直播后态度有所转变。制作人YU在直播里回答了很多问题，态度比较诚恳，也说了会根据测试反馈调整。但问题是——调整多少？什么时候改？</p><h2 id="巴哈上的核心矛盾" tabindex="-1">巴哈上的核心矛盾 <a class="header-anchor" href="#巴哈上的核心矛盾" aria-label="Permalink to &quot;巴哈上的核心矛盾&quot;">​</a></h2><p>说白了就一句话：<strong>游戏本身不差，但钱的味道太重了</strong>。</p><p>画面OK、手感OK、副本机制有想法、赛季制也新鲜——这些都是正面的。但一进商城，看到抽卡、看到精炼要氪、看到疲劳值，很多人就直接关游戏了。</p><p>有个帖子说得好：&quot;我愿意花钱买月卡买外观，但你让我花钱买战力？那跟其他RO手游有什么区别？&quot;</p><p>制作人在直播里也提到了会参考其他游戏的商业化模式（比如王者荣耀那种纯外观收费）。但问题是RO3已经公测在即了，大改系统几乎不可能，最多就是微调。</p><h2 id="我的判断" tabindex="-1">我的判断 <a class="header-anchor" href="#我的判断" aria-label="Permalink to &quot;我的判断&quot;">​</a></h2><p>启燃测试暴露出来的不是技术问题，是<strong>商业化路线的问题</strong>。</p><p>测试的目的本来就是收集反馈，现在反馈收集到了——玩家不喜欢抽卡宠物、不喜欢氪金精炼、不喜欢疲劳值。问题在于开发团队愿不愿意真的改。</p><p>RO3的底子是好的，从画面到玩法都看得出花了心思。但如果上线的时候还是这套商业模式，那大概率就是另一款&quot;出了一年就没人玩&quot;的RO手游。</p><p>祝各位好运。</p><h2 id="参考来源" tabindex="-1">参考来源 <a class="header-anchor" href="#参考来源" aria-label="Permalink to &quot;参考来源&quot;">​</a></h2><ul><li><a href="https://forum.gamer.com.tw/B.php?bsn=81475" target="_blank" rel="noreferrer">巴哈姆特：RO3 哈啦板</a></li><li><a href="https://gnn.gamer.com.tw/detail.php?sn=306111" target="_blank" rel="noreferrer">GNN：启燃测试开放招募</a></li><li><a href="https://www.facebook.com/RagnarokOnline3tc/" target="_blank" rel="noreferrer">官方FB：启燃测试资格开通通知</a></li></ul>',34)])])}const c=a(n,[["render",p]]);export{d as __pageData,c as default};
